static boolean isBalanced(String json) {
    int depth = 0;
    boolean insideString = false;
    for (char c : json.toCharArray()) {
        if (c == '"') { insideString = !insideString; continue; }
        if (insideString) continue;
        if (c == '{' || c == '[') depth++;
        else if (c == '}' || c == ']') depth--;
    }
    return depth == 0;
}

