static boolean isJsonBalanced(String json) {
    Deque<Character> stos = new ArrayDeque<>();
    boolean wString = false;
    for (char c : json.toCharArray()) {
        if (c == '"') { wString = !wString; continue; }
        if (wString) continue;
        if (c == '{' || c == '[') stos.push(c);
        else if (c == '}' ) { if (stos.isEmpty() || stos.pop() != '{') return false; }
        else if (c == ']') { if (stos.isEmpty() || stos.pop() != '[') return false; }
    }
    return stos.isEmpty();
}

static List<String> extractTopLevelKeysSimple(String json) {
    String bezNawiasow = json.substring(1, json.length() - 1);
    List<String> klucze = new ArrayList<>();
    for (String para : bezNawiasow.split(",")) {
        String klucz = para.split(":")[0].replace("\"", "").trim();
        klucze.add(klucz);
    }
    return klucze;
}

static int countArrayElements(String json) {
    String wnetrze = json.substring(1, json.length() - 1).trim();
    if (wnetrze.isEmpty()) return 0;
    return wnetrze.split(",").length;
}

static int getMaxDepth(String json) {
    int depth = 0, maxDepth = 0;
    boolean wString = false;
    for (char c : json.toCharArray()) {
        if (c == '"') { wString = !wString; continue; }
        if (wString) continue;
        if (c == '{' || c == '[') {
            depth++;
            maxDepth = Math.max(maxDepth, depth);
        } else if (c == '}' || c == ']') {
            depth--;
        }
    }
    return maxDepth;
}

static String detectValueType(String rawValue) {
    String v = rawValue.trim();
    if (v.startsWith("\"") && v.endsWith("\"")) return "string";
    if (v.equals("true") || v.equals("false")) return "boolean";
    if (v.equals("null")) return "null";
    return "number";
}

static boolean roughValidate(String json) {
    long liczbaCudzyslowow = json.chars().filter(c -> c == '"').count();
    boolean parzysteCudzyslowy = liczbaCudzyslowow % 2 == 0;
    return isJsonBalanced(json) && parzysteCudzyslowy;
}

