static List<String> jsonArrayToJavaList(String json) {
    String wnetrze = json.substring(1, json.length() - 1);
    List<String> wynik = new ArrayList<>();
    for (String element : wnetrze.split(",")) {
        wynik.add(element.trim().replaceAll("^\"|\"$", ""));
    }
    return wynik;
}

static Map<String, String> parseFlatObject(String json) {
    String wnetrze = json.substring(1, json.length() - 1);
    Map<String, String> mapa = new LinkedHashMap<>();
    for (String para : wnetrze.split(",")) {
        String[] czesci = para.split(":", 2);
        String klucz = czesci[0].trim().replaceAll("^\"|\"$", "");
        String wartosc = czesci[1].trim().replaceAll("^\"|\"$", "");
        mapa.put(klucz, wartosc);
    }
    return mapa;
}

static boolean isValidJsonStructure(String json) {
    boolean balanced = isJsonBalanced(json);
    long cudzyslowy = json.chars().filter(c -> c == '"').count();
    boolean parzyste = cudzyslowy % 2 == 0;
    boolean bezTrailingComma = !json.matches("(?s).*,\\s*[}\\]].*");
    return balanced && parzyste && bezTrailingComma;
}

