static String prettyPrintJson(String compact) {
    StringBuilder sb = new StringBuilder();
    int indent = 0;
    boolean wString = false;
    for (char c : compact.toCharArray()) {
        if (c == '"') wString = !wString;
        if (!wString && (c == '}' || c == ']')) {
            indent--;
            sb.append("\n").append("  ".repeat(indent));
        }
        sb.append(c);
        if (!wString && (c == '{' || c == '[')) {
            indent++;
            sb.append("\n").append("  ".repeat(indent));
        } else if (!wString && c == ',') {
            sb.append("\n").append("  ".repeat(indent));
        }
    }
    return sb.toString();
}

static String minifyJson(String pretty) {
    StringBuilder sb = new StringBuilder();
    boolean wString = false;
    for (char c : pretty.toCharArray()) {
        if (c == '"') wString = !wString;
        if (wString || !Character.isWhitespace(c)) {
            sb.append(c);
        }
    }
    return sb.toString();
}

static boolean compareJsonStructureOnly(String json1, String json2) {
    Set<String> klucze1 = new HashSet<>(extractTopLevelKeysSimple(json1));
    Set<String> klucze2 = new HashSet<>(extractTopLevelKeysSimple(json2));
    return klucze1.equals(klucze2);
}

static Set<String> extractAllGenres(String json) {
    Set<String> gatunki = new LinkedHashSet<>();
    Matcher m = Pattern.compile("\"genres\":\\[([^\\]]*)\\]").matcher(json);
    while (m.find()) {
        String tablica = "[" + m.group(1) + "]";
        gatunki.addAll(jsonArrayToJavaList(tablica));
    }
    return gatunki;
}

static List<String> detectDuplicateKeys(String json) {
    List<String> klucze = extractTopLevelKeysSimple(json);
    Map<String, Integer> liczniki = new HashMap<>();
    for (String k : klucze) {
        liczniki.merge(k, 1, Integer::sum);
    }
    return liczniki.entrySet().stream()
        .filter(e -> e.getValue() > 1)
        .map(Map.Entry::getKey)
        .toList();
}

