static void compareJsonValues(String json1, String json2) {
    Map<String, String> m1 = parseFlatObject(json1);
    Map<String, String> m2 = parseFlatObject(json2);

    for (String klucz : m1.keySet()) {
        if (!m2.containsKey(klucz)) {
            System.out.println("Tylko w pierwszym: " + klucz);
        } else if (!m1.get(klucz).equals(m2.get(klucz))) {
            System.out.println("Rozna wartosc dla " + klucz + ": " + m1.get(klucz) + " vs " + m2.get(klucz));
